create table if not exists public.books(id bigint generated by default as identity primary key,title text not null,authors text[] not null default '{}',isbn_10 text,isbn_13 text,publisher text,publication_year integer,edition text,language text,pages integer,genres text[] not null default '{}',cover_url text,location text,owners text[] not null default '{}',reading_status text not null default 'sin_empezar',notes text,open_library_id text,google_books_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.books enable row level security;
grant select,insert,update,delete on public.books to anon;
grant usage,select on all sequences in schema public to anon;
drop policy if exists "Acceso familiar de lectura" on public.books; drop policy if exists "Acceso familiar de alta" on public.books; drop policy if exists "Acceso familiar de edicion" on public.books; drop policy if exists "Acceso familiar de borrado" on public.books;
create policy "Acceso familiar de lectura" on public.books for select to anon using(true);
create policy "Acceso familiar de alta" on public.books for insert to anon with check(true);
create policy "Acceso familiar de edicion" on public.books for update to anon using(true) with check(true);
create policy "Acceso familiar de borrado" on public.books for delete to anon using(true);
